import { describe, it, expect } from "vitest";
import { quote, claim } from "./claim-office.js";

describe("Claim Office - quote", () => {
  // Edge case: empty item list
  it.todo("empty item list -> premium 5 G (only processing fee)");

  // Base premiums for main items (base + 5 G fee)
  it.todo("single sword -> premium 105 G (100 base + 5 fee)");
  it.todo("single amulet -> premium 65 G (60 base + 5 fee)");
  it.todo("single staff -> premium 85 G (80 base + 5 fee)");
  it.todo("single potion -> premium 45 G (40 base + 5 fee)");

  // Components
  it.todo("single rune -> premium 30 G (25 base + 5 fee)");
  it.todo("single moonstone -> premium 30 G (25 base + 5 fee)");

  // Building block of 3 alike components
  it.todo("2 runes -> 50 G base premium (55 total)");
  it.todo("3 runes -> 60 G base premium block applies (65 total)");
  it.todo("4 runes -> 100 G base premium no block (105 total)");
  it.todo("7 runes -> 175 G base premium (180 total)");

  // "Alike" components
  it.todo("2 runes + 1 moonstone -> 75 G base premium no block (80 total)");
  it.todo("3 runes + 3 moonstones -> 120 G base premium two blocks (125 total)");

  // Premium modifiers - item-specific
  it.todo("cursed sword adds 50% surcharge on item base premium");
  it.todo("highly enchanted sword (level >= 5) adds 30% surcharge");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge");
  it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge applies");
  it.todo("cursed sword with enchantment 5 -> both surcharges apply");

  // Policy-wide modifiers
  it.todo("long-standing customer (>= 2 years) receives 20% loyalty discount");
  it.todo("customer with exactly 2 years -> loyalty discount applies");
  it.todo("first insurance carries 10% initial assessment surcharge");
  it.todo("15% discount on each contract after the first");

  // Modifier scope on multi-item policies
  it.todo("cursed sword + plain amulet -> curse surcharge on cursed item only -> 210 G before fee");

  // Rounding
  it.todo("premium yielding 197.5 G -> final premium 198 G (rounded up)");

  // Integration examples
  it.todo("newcomer with cursed sword (steel, ench 3) -> premium 165 G");
  it.todo("long-standing customer second contract, cursed sword (steel, ench 7) -> premium 160 G");

  // Edge cases
  it.todo("quote with unknown item type -> throws error");
});

describe("Claim Office - claim", () => {
  // Standard reimbursement
  it.todo("regular sword damage 500 G -> payout 400 G (minus deductible)");
  it.todo("rune damage 200 G -> payout 100 G (minus deductible, no special clause)");

  // High enchantment reimbursement
  it.todo("dragon sword ench 8, damage 1000 G -> payout 400 G (50% then deductible)");
  it.todo("steel sword ench 9, damage 1000 G -> payout 400 G (50% then deductible)");

  // Dragon material
  it.todo("dragon sword ench 5, damage 800 G -> payout 700 G (full then deductible)");

  // Both clauses -> 50% wins
  it.todo("dragon sword ench 9, damage 1000 G -> payout 400 G (50% wins then deductible)");

  // Deductible per damage event
  it.todo("dragon attack damages sword 500 + amulet 300 -> payout 600 G (deductible per item)");

  // Cap
  it.todo("cap based on unmodified insurance value; two swords -> cap 4000 G");
  it.todo("cap exhaustion: two successive 1500 G claims -> 1400 then 600");

  // Multiple items same type
  it.todo("two sword damages but only one sword insured -> throws error");

  // Rounding
  it.todo("payout yielding 350.5 G -> final payout 350 G (rounded down)");

  // Edge cases
  it.todo("claim references item not in policy -> throws error");
  it.todo("claim with negative amount -> throws error");
});

