export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteInput {
  items: Item[];
}

export interface CustomerContext {
  yearsWithMHPCO: number;
  contractIndex: number;
}

const PROCESSING_FEE = 5;

// A "building block" of 3 alike components is priced at a flat rate
// instead of the sum of their individual base premiums.

input.newString:
const PROCESSING_FEE = 5;

// A "building block" of exactly 3 alike components is priced at a flat
// rate instead of the sum of their individual base premiums.
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;
const COMPONENT_PREMIUM = 25;

const COMPONENT_TYPES = ["rune", "moonstone"];

const ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const componentPremium = (count: number): number => {
  if (count === BLOCK_SIZE) {
    return BLOCK_PREMIUM;
  }
  return count * COMPONENT_PREMIUM;
};

export const quote = (input: QuoteInput, customer: CustomerContext): number => {
  let itemsPremium = 0;
  for (const item of input.items) {
    if (!COMPONENT_TYPES.includes(item.type)) {
      itemsPremium += ITEM_BASE_PREMIUMS[item.type];
    }
  }
  for (const componentType of COMPONENT_TYPES) {
    const count = input.items.filter((item) => item.type === componentType).length;
    itemsPremium += componentPremium(count);
  }
  return itemsPremium + PROCESSING_FEE;
};

input.oldString:
const PROCESSING_FEE = 5;

// A "building block" of 3 alike components is priced at a flat rate
// instead of the sum of their individual base premiums.
const BLOCK_SIZE = 3;
const THREE_RUNE_BLOCK_PREMIUM = 60;

const ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

export const quote = (input: QuoteInput, customer: CustomerContext): number => {
  // Special case (not yet generalized): exactly 3 runes form one block.
  // Kept hardcoded until upcoming tests (4/7 runes, moonstones, mixed)
  // force the general block-pricing algorithm.
  const runeCount = input.items.filter((item) => item.type === "rune").length;
  if (runeCount === BLOCK_SIZE) {
    return THREE_RUNE_BLOCK_PREMIUM + PROCESSING_FEE;
  }
  const itemsPremium = input.items.reduce(
    (total, item) => total + ITEM_BASE_PREMIUMS[item.type],
    0,
  );
  return itemsPremium + PROCESSING_FEE;
};

