export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteInput {
  items: Item[];
}

export interface CustomerContext {
  yearsWithMHPCO: number;
  contractIndex: number;
}

const PROCESSING_FEE = 5;

// A "building block" of exactly 3 alike components is priced at a flat
// rate instead of the sum of their individual base premiums.

input.newString:
export const quote = (input: QuoteInput, customer: CustomerContext): number => {
  const policyBase =
    mainItemsPremium(input.items) + componentsPremium(input.items);
  let itemSurcharges = 0;
  for (const item of input.items) {
    if (item.cursed) {
      itemSurcharges += ITEM_BASE_PREMIUMS[item.type] * 0.5;
    }
  }
  const firstInsurance = policyBase * 0.1;
  return policyBase + itemSurcharges + firstInsurance + PROCESSING_FEE;
};

