export const quote = (input: QuoteInput, customer: CustomerContext): number => {
  const policyBase =
    mainItemsPremium(input.items) + componentsPremium(input.items);
  let itemSurcharges = 0;
  for (const item of input.items) {
    if (item.cursed) {
      itemSurcharges += ITEM_BASE_PREMIUMS[item.type] * 0.5;
    }
  }
  const firstInsurance = policyBase * 0.1;
  const premium = policyBase + itemSurcharges + firstInsurance + PROCESSING_FEE;
  return Math.ceil(premium);
};

