    policyBase +
    itemSurchargesPremium(input.items) +
    firstInsuranceSurcharge(policyBase) -
    loyaltyDiscount(policyBase, customer) -
    followUpDiscount(policyBase, customer) +
    PROCESSING_FEE;
  return Math.ceil(premium);
};

