const DEDUCTIBLE = 100;

// Damage to very highly enchanted items (level >= 8) is reimbursed at 50%.
const HALF_REIMBURSEMENT_THRESHOLD = 8;
const HALF_REIMBURSEMENT_RATE = 0.5;

// Each damage is reimbursed for its (possibly reduced) amount minus a deductible.
const damagePayout = (damage: Damage, item: Item): number => {
  let reimbursed = damage.amount;
  if ((item.enchantment ?? 0) >= HALF_REIMBURSEMENT_THRESHOLD) {
    reimbursed = damage.amount * HALF_REIMBURSEMENT_RATE;
  }
  return reimbursed - DEDUCTIBLE;
};

export const claim = (policy: Policy, incident: Incident): ClaimResult => {
  const payout = incident.damages.reduce((total, damage) => {
    const item = policy.items.find((i) => i.type === damage.itemType)!;
    return total + damagePayout(damage, item);
  }, 0);
  return { payout, remainingCap: 0 };
};

