const insuredItemFor = (policy: Policy, damage: Damage): Item =>
  policy.items.find((item) => item.type === damage.itemType)!;

const policyCap = (policy: Policy): number =>
  policy.items.reduce(
    (total, item) => total + ITEM_INSURANCE_VALUES[item.type],
    0,
  ) * CAP_MULTIPLIER;

export const claim = (policy: Policy, incident: Incident): ClaimResult => {
  const payout = incident.damages.reduce(
    (total, damage) => total + damagePayout(damage, insuredItemFor(policy, damage)),
    0,
  );
  return { payout, remainingCap: policyCap(policy) - payout };
};

