export const claim = (
  policy: Policy,
  incident: Incident,
  availableCap: number = policyCap(policy),
): ClaimResult => {
  const desiredPayout = incident.damages.reduce(
    (total, damage) => total + damagePayout(damage, insuredItemFor(policy, damage)),
    0,
  );
  const payout = Math.min(desiredPayout, availableCap);
  return { payout, remainingCap: availableCap - payout };
};

